                '\n'
                'USN\n'
                '                   : 2896\n'
                'ファイル名\n'
                '                   : USN.txt\n'
                'ファイル名の長さ  : 14\n'
                '理由\n'
                '                   : 0x00001000: 改名前の名前\n'
                'タイムスタンプ\n'
                '                   : 12/8/2018 15:22:15\n'
                'ファイル属性   : 0x00000020: アーカイブ\n'
                'ファイル ID\n'
                '                   : 0000000000000000000c000000617912\n'
                '親ファイル ID    : 00000000000000000018000000617ab6\n'
                '変更元の情報\n'
                '                   : 0x00000000: なし\n'
                'セキュリティ ID\n'
